nta.declaration:
// ============================================================
// DECLARATIONS GLOBALES  (RFC 3550)
// ============================================================

// --- Canaux de synchronisation broadcast ---
broadcast chan init_session;   // Ouverture de session
broadcast chan bye_signal;     // Fermeture de session (RTCP BYE)
broadcast chan rtp_send;       // Transmission d'un paquet RTP

// --- Metadonnees du paquet RTP courant (§5.1) ---
int current_ssrc = -1;        // SSRC (32 bits)
int current_seq  =  0;        // Numero de sequence (16 bits, §5.1)
int current_ts   =  0;        // Timestamp RTP

// --- Identificateur SSRC du sender legitime ---
const int SSRC_SENDER = 1000;

// --- Variables d'etat de la session ---
int  established_ssrc  = -1;
bool session_active    = false;
int  packets_received  =  0;
bool session_closed    = false;

// --- Constantes de configuration ---
const int MAX_PKTS        = 5;
const int RTCP_INTERVAL   = 5;
const int SESSION_TIMEOUT = 20;

// ============================================================
// ATTAQUE LIEE A L'IMPLEMENTATION : Sequence Number Wrap-Around
// ============================================================
// RFC 3550 §5.1 : le numero de sequence est code sur 16 bits
// (valeurs 0..65535). Une implementation correcte doit utiliser
// l'arithmetique modulo 2^16 (RFC 3550 §A.1) pour determiner
// si un paquet est "plus recent" qu'un autre.
//
// Faille d'implementation : le Receiver maintient un compteur
// last_seq de type int (non borne), et accepte un paquet ssi
// current_seq > last_seq (comparaison entiere simple, SANS
// modulo). Un attaquant qui connait le SSRC legitime peut
// injecter quelques paquets avec des numeros de sequence tres
// eleves (proches de SEQ_MAX = 65535). Apres wrap-around, les
// paquets legitimes (seq=0, 1, 2...) semblent "anciens" au
// Receiver qui les rejette => perte totale du flux legitime.
//
// Ce n'est PAS une faille de specification (la RFC definit
// correctement le wrap-around et l'algo de detection §A.1),
// mais une faille d'IMPLEMENTATION (le developpeur a omis
// l'arithmetique modulaire).
// ============================================================

// UPPAAL utilise des int signes 16 bits (-32768..32767).
// On simule le wrap-around sur un espace de seq reduit (0..15, soit 4 bits)
// pour rester dans les bornes. La logique d'attaque est identique.
const int SEQ_MAX    = 15;  // Valeur maximale (espace 4 bits : 0..15)
const int SSRC_ATK   = 1000; // Meme SSRC que le sender (paquet forge)
const int ATK_SEQ_START = 13; // L'attaquant commence pres du max (13,14,15)
const int ATK_PKTS   = 3;    // Nombre de paquets injectes

int  last_seq_seen   = -1;    // Dernier seq accepte par le Receiver
bool impl_attack_done = false; // Fin d'injection attaquant
bool legit_pkt_rejected = false; // Un paquet legitime a ete rejete

template.declaration:
// ============================================================
// Implementation VULNERABE :
//   Accepte un paquet ssi current_seq > last_seq_seen
//   (comparaison entiere simple, SANS arithmetique modulo 2^16)
//
// Implementation CORRECTE (RFC 3550 §A.1) aurait utilise :
//   delta = (current_seq - last_seq_seen) mod 65536
//   accepter ssi 0 < delta < 32768
// ============================================================
clock t_rx;

// ============================================================
// Attacker : Sequence Number Wrap-Around Attack
//
// Strategie :
//   1. Attendre que la session soit etablie (established_ssrc connu).
//   2. Injecter ATK_PKTS paquets avec le MEME SSRC que le sender
//      legitime (SSRC_ATK = SSRC_SENDER = 1000) mais avec des
//      numeros de sequence tres eleves (ATK_SEQ_START = 65533).
//   3. Le Receiver (implementation vulnerable) met last_seq_seen
//      a 65535 apres le dernier paquet attaquant.
//   4. Les paquets legitimes suivants (seq=1,2,3...) ont
//      current_seq < last_seq_seen => REJETES.
//
// Pourquoi c'est une attaque d'IMPLEMENTATION et non de spec :
//   - La RFC 3550 §A.1 definit explicitement l'algo de detection
//     de "paquet plus recent" via arithmetique modulo 2^16.
//   - Une implementation conforme aurait rejete les paquets de
//     l'attaquant (delta > 32768 => considered old).
//   - Seul un Receiver qui omet le modulo est vulnerable.
// ============================================================
clock t_atk;
int   atk_pkt;
int   atk_seq;

nta.system:
sender   = Sender();
receiver = Receiver();
rtcp     = RTCP_Manager();
attacker = Attacker();

system sender, receiver, rtcp, attacker;
